/**
 * Plant catalog — Gardyn's published facts (light zone, first-harvest window,
 * care level, yield) plus rule-derived fields, generated by
 * scripts/plants/build-catalog.py into data/catalog.json. Provenance and the
 * cross-check against My Pod Planner live in knowledge/plants/.
 */
import { z } from 'zod'
import raw from './catalog.json'

export const Zone = z.enum(['high', 'medium', 'low'])
export type Zone = z.infer<typeof Zone>

export const Category = z.enum(['fruiting', 'vegetable', 'legume', 'flower', 'herb', 'green', 'lettuce'])
export type Category = z.infer<typeof Category>

/** Gardyn's succession-planting groups. */
export const Succession = z.enum(['fast-greens', 'long-greens-herbs', 'fast-fruiting', 'long-fruiting', 'flowers'])
export type Succession = z.infer<typeof Succession>

export const Plant = z.object({
  id: z.string(),
  name: z.string(),
  category: Category,
  zone: Zone,
  /** First harvest window in months after starting the yCube. */
  harvestMonths: z.tuple([z.number().int(), z.number().int()]),
  /** True when Gardyn publishes no window and the category median is used. */
  harvestEstimated: z.boolean(),
  careLevel: z.enum(['beginner', 'intermediate', 'expert']).nullable(),
  yield: z.enum(['light', 'generous', 'bountiful']).nullable(),
  succession: Succession,
  successionInferred: z.boolean(),
  /** 'large' plants shade neighbours; the planner spaces them apart. */
  size: z.enum(['large', 'normal']),
  /** Gardyn's explicit exception: cucumbers start bottom-centre and climb into the light. */
  placement: z.enum(['bottomCenter']).nullable(),
  gardynHandle: z.string().nullable(),
  inStore: z.boolean(),
})
export type Plant = z.infer<typeof Plant>

const Catalog = z.object({
  version: z.literal(1),
  sources: z.record(z.string(), z.string()),
  plants: z.array(Plant),
})

const catalog = Catalog.parse(raw)

export const PLANTS: readonly Plant[] = catalog.plants
export const CATALOG_SOURCES = catalog.sources
const byId = new Map(PLANTS.map(p => [p.id, p]))

export function getPlant(id: string): Plant | undefined {
  return byId.get(id)
}

/** Case/punctuation-insensitive lookup by id or name (for free-text pod names). */
export function findPlant(query: string): Plant | undefined {
  const q = query.toLowerCase().replace(/[^a-z0-9]+/g, '')
  return byId.get(query) ?? PLANTS.find(p => p.name.toLowerCase().replace(/[^a-z0-9]+/g, '') === q)
}

export interface PlantFilter {
  q?: string
  category?: Category
  zone?: Zone
  inStore?: boolean
  careLevel?: 'beginner' | 'intermediate' | 'expert'
}

export function searchPlants(f: PlantFilter = {}): Plant[] {
  const q = f.q?.toLowerCase().trim()
  return PLANTS.filter(p =>
    (!q || p.name.toLowerCase().includes(q) || p.id.includes(q))
    && (!f.category || p.category === f.category)
    && (!f.zone || p.zone === f.zone)
    && (f.inStore === undefined || p.inStore === f.inStore)
    && (!f.careLevel || p.careLevel === f.careLevel))
}

/**
 * Gardyn's succession table: "start the next yCube about every…", as days
 * after the previous plant reaches harvest-ready maturity (greens/herbs) or
 * after reliable harvesting begins (fruiting). Midpoint of Gardyn's range.
 * Flowers: "as flowering declines" — no fixed cadence.
 */
export const SUCCESSION_GAP_DAYS: Record<Succession, number | null> = {
  'fast-greens': 10, // ~1–2 weeks
  'long-greens-herbs': 21, // 2–4 weeks
  'fast-fruiting': 31, // 3–6 weeks
  'long-fruiting': 56, // 6–10+ weeks
  'flowers': null,
}
